ALTER TABLE "checkout_attempts" DROP CONSTRAINT "checkout_attempts_provider_state_consistent";--> statement-breakpoint
ALTER TABLE "checkout_attempts" ADD COLUMN "stripe_charge_id" varchar(255);--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "refunded_amount_cents" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "checkout_attempts_stripe_charge_id_unique_idx" ON "checkout_attempts" USING btree ("stripe_charge_id");--> statement-breakpoint
ALTER TABLE "checkout_attempts" ADD CONSTRAINT "checkout_attempts_provider_state_consistent" CHECK (("checkout_attempts"."status" = 'created' AND "checkout_attempts"."stripe_session_id" IS NULL AND "checkout_attempts"."payment_intent_id" IS NULL AND "checkout_attempts"."stripe_charge_id" IS NULL AND "checkout_attempts"."stripe_expires_at" IS NULL AND "checkout_attempts"."checkout_ready_at" IS NULL AND "checkout_attempts"."terminal_at" IS NULL) OR ("checkout_attempts"."status" = 'ready' AND "checkout_attempts"."stripe_session_id" IS NOT NULL AND "checkout_attempts"."stripe_charge_id" IS NULL AND "checkout_attempts"."stripe_expires_at" IS NOT NULL AND "checkout_attempts"."checkout_ready_at" IS NOT NULL AND "checkout_attempts"."terminal_at" IS NULL) OR ("checkout_attempts"."status" = 'completed' AND "checkout_attempts"."stripe_session_id" IS NOT NULL AND "checkout_attempts"."payment_intent_id" IS NOT NULL AND "checkout_attempts"."stripe_charge_id" IS NOT NULL AND "checkout_attempts"."stripe_expires_at" IS NOT NULL AND "checkout_attempts"."checkout_ready_at" IS NOT NULL AND "checkout_attempts"."terminal_at" IS NOT NULL) OR ("checkout_attempts"."status" = 'expired' AND "checkout_attempts"."stripe_session_id" IS NOT NULL AND "checkout_attempts"."stripe_charge_id" IS NULL AND "checkout_attempts"."stripe_expires_at" IS NOT NULL AND "checkout_attempts"."checkout_ready_at" IS NOT NULL AND "checkout_attempts"."terminal_at" IS NOT NULL) OR ("checkout_attempts"."status" = 'failed' AND "checkout_attempts"."stripe_session_id" IS NULL AND "checkout_attempts"."payment_intent_id" IS NULL AND "checkout_attempts"."stripe_charge_id" IS NULL AND "checkout_attempts"."stripe_expires_at" IS NULL AND "checkout_attempts"."checkout_ready_at" IS NULL AND "checkout_attempts"."terminal_at" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_refund_amount_valid" CHECK ("orders"."refunded_amount_cents" >= 0 AND "orders"."refunded_amount_cents" <= "orders"."total_cents");--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_refund_status_consistent" CHECK (("orders"."payment_status" IN ('pending', 'paid', 'expired', 'failed', 'cancelled') AND "orders"."refunded_amount_cents" = 0) OR ("orders"."payment_status" = 'partially_refunded' AND "orders"."refunded_amount_cents" > 0 AND "orders"."refunded_amount_cents" < "orders"."total_cents") OR ("orders"."payment_status" = 'refunded' AND "orders"."total_cents" > 0 AND "orders"."refunded_amount_cents" = "orders"."total_cents"));